    const ev = (f) => pvp(ctx, off, f, c, 0, m);
    // Expressions that rewrite a shape read its geometry off `thisProperty`.
    if (ctx.expr && tag === T_PATH) ev.pathv = (m[0] = mkPath(S, off));
